package com.cpf.education.online.transactionrequiresnew.service;
import com.cpf.data.persistence.api.CpfCrudRepository; import com.cpf.data.persistence.api.annotation.CpfTransactional; import com.cpf.education.online.transactionrequiresnew.dto.OrderProcessingCommand; import com.cpf.education.online.transactionrequiresnew.repository.OrderTransactionRecord; import com.cpf.foundation.annotation.CpfService; import org.springframework.beans.factory.ObjectProvider; import org.springframework.transaction.annotation.Propagation;
@CpfService
/** OrderProcessingService는 Outer REQUIRED와 독립 REQUIRES_NEW 경계를 서로 다른 Service Bean으로 보여주는 Transaction Golden Path입니다. */
public class OrderProcessingService { private final IndependentAuditService audit; private final ObjectProvider<CpfCrudRepository<OrderTransactionRecord,String>> repositories; public OrderProcessingService(IndependentAuditService audit,ObjectProvider<CpfCrudRepository<OrderTransactionRecord,String>> repositories){this.audit=audit;this.repositories=repositories;}
 @CpfTransactional(propagation=Propagation.REQUIRED) public void process(OrderProcessingCommand c){repository().save(new OrderTransactionRecord(c.orderId(),"ORDER","pending"));audit.record(c.auditId());if(c.failOuter())throw new IllegalStateException("outer transaction rolls back after independent audit commit");repository().save(new OrderTransactionRecord(c.orderId(),"ORDER","completed"));} private CpfCrudRepository<OrderTransactionRecord,String> repository(){var r=repositories.getIfAvailable();if(r==null)throw new IllegalStateException("CPF transaction repository is not configured");return r;} }
